<script setup lang="ts">
import { computed,onMounted,reactive,ref,watch } from 'vue'
import { ElMessage } from 'element-plus'
import AppShell from '@/components/AppShell.vue'
import { createKnowledgeSource,listKnowledgeDocuments,listKnowledgeSources,parseKnowledgeDocument,searchKnowledge,uploadKnowledgeDocument,type KnowledgeDocument,type KnowledgeHit,type KnowledgeSource } from '@/api/knowledge'
const sources=ref<KnowledgeSource[]>([]),documents=ref<KnowledgeDocument[]>([]),hits=ref<KnowledgeHit[]>([]);const selectedId=ref(''),query=ref(''),loading=ref(false),sourceDialog=ref(false),uploadDialog=ref(false),uploadFile=ref<File>();
const selected=computed(()=>sources.value.find(item=>item.id===selectedId.value));const sourceForm=reactive({sourceCode:'',sourceName:'',category:'单位制度',storageType:'全文索引',permissionScope:'本单位'});const uploadForm=reactive({title:'',authorityLevel:'单位制度',permissionLevel:'内部'});
function fail(reason:unknown,fallback:string){ElMessage.error(reason instanceof Error?reason.message:fallback)}
async function load(){loading.value=true;try{sources.value=await listKnowledgeSources();selectedId.value||=sources.value[0]?.id??''}catch(r){fail(r,'知识库加载失败')}finally{loading.value=false}}
async function loadDocuments(id:string){documents.value=id?await listKnowledgeDocuments(id):[]}
async function saveSource(){try{const created=await createKnowledgeSource({...sourceForm});sources.value.push(created);selectedId.value=created.id;sourceDialog.value=false;Object.assign(sourceForm,{sourceCode:'',sourceName:''});ElMessage.success('知识库已创建')}catch(r){fail(r,'知识库创建失败')}}
async function upload(){if(!selected.value||!uploadFile.value){ElMessage.warning('请选择文件');return}try{const created=await uploadKnowledgeDocument(selected.value.id,uploadFile.value,{...uploadForm});documents.value.unshift(created);uploadDialog.value=false;uploadFile.value=undefined;ElMessage.success('文档已上传，等待解析')}catch(r){fail(r,'文档上传失败')}}
async function parse(item:KnowledgeDocument){if(!selected.value)return;try{await parseKnowledgeDocument(selected.value.id,item.id);item.parsedStatus='解析中';ElMessage.success('解析任务已提交，可在“任务运行”中查看进度')}catch(r){fail(r,'解析任务提交失败')}}
async function search(){if(query.value.trim().length<2){ElMessage.warning('请输入至少两个字符');return}try{hits.value=await searchKnowledge(query.value,selectedId.value)}catch(r){fail(r,'检索失败')}}
watch(selectedId,id=>loadDocuments(id).catch(r=>fail(r,'文档加载失败')));onMounted(load)
</script>
<template><AppShell><template #title>知识与依据中心</template><section class="knowledge-center" v-loading="loading"><header class="knowledge-hero"><div><span class="section-no">TRUSTED KNOWLEDGE</span><h2>每一个结论，<br><em>都能回到它的出处。</em></h2></div><form @submit.prevent="search"><input v-model="query" placeholder="检索政策、制度、历史公文…"><button type="submit">检索依据</button></form></header><div class="knowledge-grid"><aside class="knowledge-sources"><header><div><span class="section-no">01</span><h3>知识库</h3></div><button type="button" @click="sourceDialog=true">＋ 新建</button></header><button v-for="item in sources" :key="item.id" type="button" :class="{active:item.id===selectedId}" @click="selectedId=item.id"><span>{{ item.category.slice(0,1) }}</span><div><strong>{{ item.sourceName }}</strong><small>{{ item.storageType }} · {{ item.entryCount }} 份</small></div></button><div v-if="!sources.length" class="governance-empty">尚无知识库。</div></aside><main class="knowledge-stage"><template v-if="hits.length"><header class="knowledge-title"><div><span class="section-no">SEARCH RESULT</span><h3>检索结果</h3></div><button type="button" @click="hits=[]">返回文档库</button></header><article v-for="hit in hits" :key="hit.chunkId" class="knowledge-hit"><header><span>{{ hit.sourceName }} / {{ hit.documentTitle }}</span><b>{{ Math.round(hit.score*100) }}%</b></header><p>{{ hit.snippet }}</p><footer><span>{{ hit.authorityLevel }} · {{ hit.permissionLevel }}</span><code>{{ hit.fileHash.slice(0,12) }}…</code></footer></article></template><template v-else-if="selected"><header class="knowledge-title"><div><span class="section-no">02</span><h3>{{ selected.sourceName }}</h3><p>{{ selected.sourceCode }} · {{ selected.category }}</p></div><button class="primary-button" type="button" @click="uploadDialog=true">上传知识文档</button></header><div class="knowledge-doc-head"><span>文档标题</span><span>权限 / 权威性</span><span>解析状态</span><span>操作</span></div><article v-for="doc in documents" :key="doc.id" class="knowledge-doc"><strong>{{ doc.documentTitle }}<small>V{{ doc.documentVersion }} · {{ doc.originalFileHash?.slice(0,10) }}</small></strong><span>{{ doc.permissionLevel }} / {{ doc.authorityLevel }}</span><b :data-status="doc.parsedStatus">{{ doc.parsedStatus }}<small>{{ doc.chunkCount }} 切片</small></b><button v-if="doc.parsedStatus!=='已完成'" type="button" @click="parse(doc)">开始解析</button><i v-else>可检索</i></article><div v-if="!documents.length" class="knowledge-empty">上传 TXT、Markdown、CSV、DOCX 或可提取文本的 PDF。</div></template></main></div></section>
<el-dialog v-model="sourceDialog" title="创建知识库" width="520px" class="task-dialog"><el-form label-position="top"><div class="form-pair"><el-form-item label="知识库代码"><el-input v-model="sourceForm.sourceCode" /></el-form-item><el-form-item label="知识库名称"><el-input v-model="sourceForm.sourceName" /></el-form-item></div><div class="form-pair"><el-form-item label="分类"><el-select v-model="sourceForm.category"><el-option v-for="v in ['国家政策','地方政策','单位制度','历史公文','业务资料','公文范文']" :key="v" :value="v" /></el-select></el-form-item><el-form-item label="存储类型"><el-select v-model="sourceForm.storageType"><el-option value="全文索引" /><el-option value="混合" disabled /></el-select></el-form-item></div><el-form-item label="权限范围"><el-input v-model="sourceForm.permissionScope" /></el-form-item></el-form><template #footer><button class="secondary-button" type="button" @click="sourceDialog=false">取消</button><button class="primary-button" type="button" @click="saveSource">创建</button></template></el-dialog>
<el-dialog v-model="uploadDialog" title="上传知识文档" width="520px" class="task-dialog"><el-form label-position="top"><el-form-item label="选择文件"><input type="file" accept=".txt,.md,.csv,.docx,.pdf" @change="uploadFile=($event.target as HTMLInputElement).files?.[0]" /></el-form-item><el-form-item label="文档标题"><el-input v-model="uploadForm.title" placeholder="留空时使用文件名" /></el-form-item><div class="form-pair"><el-form-item label="权威等级"><el-input v-model="uploadForm.authorityLevel" /></el-form-item><el-form-item label="数据权限"><el-select v-model="uploadForm.permissionLevel"><el-option v-for="v in ['公开','内部','秘密','机密']" :key="v" :value="v" /></el-select></el-form-item></div></el-form><template #footer><button class="secondary-button" type="button" @click="uploadDialog=false">取消</button><button class="primary-button" type="button" @click="upload">上传</button></template></el-dialog></AppShell></template>
